import fs from 'fs';
import path from 'path';
import { MATEMATICA_7B_OA04_CLASE01 } from './oa04_data/clase01';
import { MATEMATICA_7B_OA04_CLASE02 } from './oa04_data/clase02';
import { MATEMATICA_7B_OA04_CLASE03 } from './oa04_data/clase03';
import { MATEMATICA_7B_OA04_CLASE04 } from './oa04_data/clase04';
import { MATEMATICA_7B_OA04_CLASE05 } from './oa04_data/clase05';
import { MATEMATICA_7B_OA04_CLASE06 } from './oa04_data/clase06';
import { LessonData } from '../Web Studio Simple/src/types/lesson';

const lessons: LessonData[] = [
  MATEMATICA_7B_OA04_CLASE01,
  MATEMATICA_7B_OA04_CLASE02,
  MATEMATICA_7B_OA04_CLASE03,
  MATEMATICA_7B_OA04_CLASE04,
  MATEMATICA_7B_OA04_CLASE05,
  MATEMATICA_7B_OA04_CLASE06
];

export function exportOa04ToMarkdown(targetDir: string = 'staging_preparacion_aislada/oa04_markdown') {
  const resolvedTarget = path.resolve(process.cwd(), targetDir);
  if (!fs.existsSync(resolvedTarget)) {
    fs.mkdirSync(resolvedTarget, { recursive: true });
  }

  lessons.forEach((l, idx) => {
    const md = lessonToMarkdown(l, idx);
    const fname = `CLASE0${idx + 1}.md`;
    const outPath = path.join(resolvedTarget, fname);
    fs.writeFileSync(outPath, md, 'utf8');
    console.log(`✓ Exportado candidato aislado: ${outPath} (${fs.statSync(outPath).size} bytes)`);
  });
}

function lessonToMarkdown(l: any, idx: number): string {
  const n = idx + 1;
  const meta = l.metadata;
  let md = `# EstudioSimple | Lección interactiva\n\n`;
  md += `## 7° básico · Matemática · OA04 · Clase 0${n}\n\n`;
  md += `**Curso App:** 110-7  \n`;
  md += `**Asignatura App:** Matematica  \n`;
  md += `**Código curricular:** 7B-MAT-OA04  \n`;
  md += `**Título:** ${meta.lessonTitle}  \n`;
  md += `**Duración:** 30 minutos  \n`;
  md += `**Número de clase:** 0${n} de 06  \n`;
  md += `**Título de trabajo de la siguiente clase:** ${meta.nextLessonTitle || 'Consolidación de porcentajes'}  \n`;
  md += `**Estado:** BORRADOR PARA REVISIÓN · EN_REVISION · AISLADO  \n`;
  md += `**Fuente principal:** Texto Escolar de Matemática 7° básico MINEDUC, Unidad 1 (Porcentajes).  \n`;
  md += `**Unidades de contenido:** 7B-MAT-OA04-C0${n}.  \n`;
  md += `**Indicador priorizado:** 7B-MAT-OA04-IE0${n}.\n\n`;

  md += `### Objetivo oficial de aprendizaje\n\n`;
  md += `Mostrar que comprenden el concepto de porcentaje: representándolo de manera pictórica, calculando de varias maneras, aplicándolo a situaciones sencillas.\n\n`;

  md += `### Objetivo de esta clase\n\n`;
  md += `**${l.prep.adultObjective}**\n\n`;
  md += `**Resultado observable:** ${l.prep.routeToday}\n\n`;

  md += `## 1. Paso 1 — Preparación del mentor\n\n`;
  md += `**Propósito:** ${l.prep.adultObjective}\n\n`;
  md += `**DILE:** “${l.prep.mentorReminder}”\n\n`;
  md += `**Ruta:** ${l.prep.routeToday}\n\n`;
  md += `**Pautas para el mentor:**\n\n`;
  (l.prep.reminders || []).forEach((r: string, i: number) => {
    md += `${i + 1}. ${r}\n`;
  });
  md += `\n**Clima de aprendizaje:** ${l.prep.emotionalTip || 'Acompaña con paciencia y valora el razonamiento.'}\n\n`;

  md += `## 2. Paso 2A — Ruta de aprendizaje\n\n`;
  md += `| N.º | Bloque | Acción | Color |\n|---|---|---|---|\n`;
  (l.route.blocks || []).forEach((b: any, i: number) => {
    md += `| ${i + 1} | ${b.title} | ${b.subtitle} | ${b.color} |\n`;
  });
  md += `\n**DILE — Objetivo del estudiante:** “${l.route.dileObjective}”\n\n`;

  md += `## 3. Paso 2B — Punto de partida\n\n`;
  md += `### Activación\n\n`;
  md += `**DILE:** “${l.situation.dilePrompt}”\n\n`;
  md += `**Respuesta esperada:** ${l.situation.expectedAnswer}\n\n`;
  md += `**Pista socrática:** “${l.situation.socraticHint || ''}”\n\n`;
  md += `**Tip emocional:** ${l.situation.emotionalTip || ''}\n\n`;

  md += `### Punto de partida\n\n`;
  md += `**DILE:** “${l.reference.dilePrompt || ''}”\n\n`;
  md += `**Pregunta:** ${l.reference.question || ''}\n\n`;
  md += `**Respuesta de referencia:** ${l.reference.expectedAnswer || ''}\n\n`;
  md += `**Retroalimentación correcta:** ${l.reference.feedbackSuccess || '¡Muy bien fundamentado!'}\n\n`;
  md += `**Retroalimentación con apoyo:** ${l.reference.feedbackSupport || 'Revisa la cuadrícula para confirmar la cantidad.'}\n\n`;

  md += `## 4. Paso 3 — Videos\n\n`;
  md += `### Gancho y explicación en 14 láminas\n\n`;
  const allSlides = [...(l.hook?.slides || []), ...(l.formalization?.slides || [])];
  allSlides.forEach((s: any, i: number) => {
    const sNum = i + 1;
    const dur = s.duracionSeg || 8;
    md += `#### Diapositiva 0${sNum < 10 ? '0' + sNum : sNum} — ${s.tituloMomento || `Momento ${sNum}`}\n\n`;
    md += `- **Texto visible:** “${s.overlayText || s.overlayTitle || ''}”\n`;
    if (s.overlaySubtitle) {
      md += `- **Subtítulo:** “${s.overlaySubtitle}”\n`;
    }
    md += `- **Duración estimada:** ${dur} segundos\n`;
    md += `- **Imagen:** ${s.visualPrompt || ''}\n`;
    md += `- **Locución:** “${s.speakerNotes || ''}”\n\n`;
  });

  md += `## 5. Paso 4 — Conversación guiada\n\n`;
  (l.preQuestions || []).forEach((q: any, i: number) => {
    md += `### Conversación ${i + 1}\n\n`;
    md += `- **Contexto:** ${q.context || ''}\n`;
    md += `- **DILE:** “${q.question || ''}”\n`;
    md += `- **Respuesta esperada:** ${q.expected || ''}\n`;
    md += `- **Éxito:** ${q.success || ''}\n`;
    md += `- **Apoyo:** “${q.support || ''}”\n`;
    md += `- **Revelación para el mentor:** ${q.reveal || ''}\n`;
    md += `- **Revelación estudiante:** “${q.studentReveal || ''}”\n\n`;
  });

  md += `## 6. Paso 5 — Formalización e idea clave\n\n`;
  md += `**Concepto:** ${l.formalization.concept || meta.lessonTitle}\n\n`;
  md += `**Idea clave:** ${l.formalization.concept || meta.lessonTitle}\n\n`;
  md += `**DILE:** “${l.formalization.dileIntro || 'Ahora formalizamos la regla de oro.'}”\n\n`;
  md += `**HAZ:** ${l.formalization.hazInstruction || 'Escribe la regla en tu cuaderno.'}\n\n`;

  md += `## 7. Paso 5B — Comprobación\n\n`;
  (l.postQuestions || []).forEach((pq: any, i: number) => {
    md += `### Comprobación ${i + 1}\n\n`;
    md += `**Pregunta:** “${pq.question || ''}”\n\n`;
    md += `**Respuesta esperada:** ${pq.expected || ''}\n\n`;
  });

  md += `## 8. Paso 6 — Práctica conjunta y autónoma\n\n`;
  (l.practice || []).slice(0, 2).forEach((p: any, i: number) => {
    md += `### Caso ${i + 1}\n\n`;
    md += `- **Contexto:** ${p.context || `Caso de práctica ${i + 1}`}\n`;
    md += `- **Pregunta:** “${p.question || ''}”\n`;
    md += `- **Respuesta de referencia:** ${p.expected || ''}\n`;
    md += `- **Criterio:** ${p.success || 'Resuelve aplicando la definición de porcentaje'}\n`;
    md += `- **Apoyo:** “${p.support || 'Revisa el total de 100 partes.'}”\n\n`;
  });

  const p3 = (l.practice || [])[2];
  md += `### Aplicación autónoma y transferencia\n\n`;
  md += `**Recurso nuevo visible para el estudiante:** ${p3 ? p3.context : 'Situación nueva de aplicación de porcentaje.'}\n\n`;
  md += `**Actividad del estudiante:** ${p3 ? p3.question : 'Calcula o representa el porcentaje en el cuaderno.'}\n\n`;
  md += `**Criterio privado del mentor, revelar solo después del intento:** ${p3 ? p3.expected : 'Aplica correctamente la razón de consecuente 100.'}\n\n`;
  md += `**Cómo valorar:** ${p3 ? p3.support : 'Comprueba que identifique la relación con 100 unidades.'}\n\n`;

  md += `## 9. Paso 7 — Miniquiz y recuperación\n\n`;
  const letters = ['A', 'B', 'C', 'D'];
  (l.mini || []).forEach((m: any, i: number) => {
    md += `### Reactivo ${i + 1}\n\n`;
    md += `${m.q}\n\n`;

    let correctLetter = 'A';
    (m.options || []).forEach((opt: string, optIdx: number) => {
      // Si la opción ya tiene prefijo tipo "A. " o "A) ", limpiarlo
      const cleanOpt = opt.replace(/^[A-D][.)]\s*/, '').trim();
      const letCode = letters[optIdx] || 'A';
      const cleanCorrect = (m.correct || '').replace(/^[A-D][.)]\s*/, '').trim();
      if (cleanOpt === cleanCorrect || opt === m.correct) {
        correctLetter = letCode;
      }
    });

    (m.options || []).forEach((opt: string, optIdx: number) => {
      const cleanOpt = opt.replace(/^[A-D][.)]\s*/, '').trim();
      const letCode = letters[optIdx] || 'A';
      md += `- ${letCode}. ${cleanOpt}\n`;
    });

    md += `\n**Clave privada:** ${correctLetter}.\n\n`;
    md += `**Explicación formativa:** ${m.fixExplain || 'Revisa el concepto clave para fundamentar tu respuesta.'}\n\n`;
  });

  // Recuperación
  md += `### Recuperación\n\n`;
  (l.recovery || []).forEach((r: any, rIdx: number) => {
    md += `#### Nueva práctica para el reactivo ${rIdx + 1}\n\n`;
    md += `**Enseñanza:** ${r.explain || 'Revisa el concepto central.'}\n\n`;
    md += `**Pista:** ${r.fixText || 'Relee la definición y calcula paso a paso.'}\n\n`;
    md += `**Tarea nueva del estudiante:** ${r.q}\n\n`;
    md += `**Apoyo 1:** ${r.fixText || 'Identifica la cantidad sobre 100 partes.'}\n\n`;
    md += `**Apoyo 2:** ${r.support2 || 'Aplica la regla de tres o razón directa.'}\n\n`;
    md += `**Apoyo 3 y modelo privado:** ${r.correctText || r.correct || 'Aplica la definición directa.'}\n\n`;
    md += `**Criterio de salida de esta práctica:** Resolver la tarea en el cuaderno físico y fundamentar la respuesta.\n\n`;
  });

  md += `## 10. Paso 8 — Síntesis y cierre\n\n`;
  md += `### Tres ideas para recordar\n\n`;
  (l.summaryIdeas || []).forEach((si: any, idx: number) => {
    const title = Array.isArray(si) ? si[0] : (si.title || `Idea ${idx + 1}`);
    const desc = Array.isArray(si) ? si[1] : (si.desc || '');
    md += `${idx + 1}. **${title}:** ${desc}\n`;
  });

  md += `\n**Pregunta de síntesis:** ¿Qué aprendiste hoy sobre el cálculo y significado de los porcentajes?\n\n`;
  md += `**Metacognición:** ¿Qué método te resultó más sencillo para encontrar el porcentaje?\n\n`;
  md += `**Celebración:** ¡Excelente trabajo matemático hoy! Has consolidado el concepto de porcentaje.\n`;

  return md;
}

if (process.argv[1]?.endsWith('export_oa04_to_markdown.ts')) {
  exportOa04ToMarkdown();
}

